import{_ as s,o as e,c as i,a2 as a}from"./chunks/framework.Wk4ah3nE.js";const u=JSON.parse('{"title":"Proxmox VM Autoscale","titleTemplate":"Right-size Proxmox VMs automatically","description":"Threshold-based CPU and RAM autoscaling for Proxmox VE virtual machines — a systemd service that drives qm over SSH, with hotplug support, host safety limits and Gotify/SMTP notifications.","frontmatter":{"layout":"home","title":"Proxmox VM Autoscale","titleTemplate":"Right-size Proxmox VMs automatically","description":"Threshold-based CPU and RAM autoscaling for Proxmox VE virtual machines — a systemd service that drives qm over SSH, with hotplug support, host safety limits and Gotify/SMTP notifications.","hero":{"name":"Proxmox VM Autoscale","text":"Right-size your VMs while they run","tagline":"A small systemd service that watches CPU and RAM on your Proxmox VE guests and adjusts cores and memory through qm over SSH — with hotplug, host safety limits and notifications.","image":{"src":"/favicon.svg","alt":"Proxmox VM Autoscale"},"actions":[{"theme":"brand","text":"Get started","link":"/guide/"},{"theme":"alt","text":"Installation","link":"/guide/installation"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/fabriziosalmi/proxmox-vm-autoscale"}]},"features":[{"icon":"📈","title":"Threshold-based scaling","details":"Scale cores and RAM up past a high-water mark and back down below a low one. One step per decision, bounded by limits you set, rate-limited by a per-resource cooldown.","link":"/guide/how-it-works","linkText":"How decisions are made"},{"icon":"⚡","title":"Live changes where possible","details":"With hotplug and NUMA enabled, vCPU and balloon memory changes apply to a running guest. Where they cannot, the service says so in the log instead of pretending.","link":"/guide/hotplug","linkText":"Hotplug and NUMA"},{"icon":"🛡️","title":"Host safety first","details":"Every scaling decision is gated on the host itself having headroom. If the node is above your CPU or RAM ceiling, nothing scales up on it.","link":"/guide/host-limits","linkText":"Host safety limits"},{"icon":"🔔","title":"Notifications that mean something","details":"Gotify push and SMTP email on real scaling actions and on errors — not on every poll. Both optional, both independent.","link":"/guide/notifications","linkText":"Configure notifications"},{"icon":"🧾","title":"Usage tracking for hosters","details":"Records every spec change with a timestamp and turns a period into a costed CSV report. Useful if you bill customers for what they actually consumed.","link":"/guide/billing","linkText":"Billing tracking"},{"icon":"🔐","title":"Root SSH, treated seriously","details":"The service holds credentials for root on your hypervisors. The security section documents exactly what that exposes and how to narrow it.","link":"/security/","linkText":"Threat model"}],"head":[["link",{"rel":"canonical","href":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/"}],["meta",{"property":"og:url","content":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/"}],["meta",{"property":"og:title","content":"Proxmox VM Autoscale"}],["meta",{"property":"og:description","content":"Threshold-based CPU and RAM autoscaling for Proxmox VE virtual machines — a systemd service that drives qm over SSH, with hotplug support, host safety limits and Gotify/SMTP notifications."}]]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),o={name:"index.md"};function n(l,t,r,h,d,c){return e(),i("div",null,[...t[0]||(t[0]=[a("",5)])])}const m=s(o,[["render",n]]);export{u as __pageData,m as default};
